/**
 * Miao village material pack (v1), 32 voxel finishes (block ids 122-153) plus
 * four decoration atlases. PNGs are generated by tools/maps/miao-village-textures.py
 * and served by the site's own nginx under /textures/miao-v1/{32,64,128}.
 *
 * The pack is independent from pharaoh-v1: only a map whose `assetBundle` is
 * `miao-v1` preloads it (see asset-bundles.ts). Atlases do not consume voxel
 * material slots; they are sampled by DecorPlane quads through the atlas UV rect.
 */
import manifest from '../../../public/textures/miao-v1/manifest.json';

export type MiaoTextureResolution = 32 | 64 | 128;

