  122: 'fir_dark_oiled',
  123: 'fir_honey_worn',
  124: 'fir_grey_weathered',
  125: 'wood_plank_floor',
  126: 'wood_lattice',
  127: 'tile_blue_grey',
  128: 'tile_grey_weathered',
  129: 'tile_moss_edges',
  130: 'stone_rubble_wall',
  131: 'stone_cut_grey',
  132: 'paving_bluestone',
  133: 'paving_cobble',
  134: 'paving_wet',
  135: 'water_jade_river',
  136: 'earth_compacted',
  137: 'mud_paddy',
  138: 'grass_mountain',
  139: 'rice_young',
  140: 'rice_gold',
  141: 'vegetable_dark',
  142: 'bamboo_leaf',
  143: 'bamboo_culm',
  144: 'foliage_maple',
